namespace WinInspector.Core.Cli;
public sealed record CliOptions(string Mode,string[] Targets,string[] Excludes,string? OutputDir,int UnusedDays=365,int FolderDepth=3,bool NoPause=false,bool Elevate=false,string? ConfigWarning=null);
public static class CliParser { public static CliOptions Parse(string[] args){string mode="All";string? outDir=null;var targets=new List<string>();var excludes=new List<string>();var unused=365;var depth=3;var pause=false;var elevate=false;for(int i=0;i<args.Length;i++){string Next()=>i+1<args.Length?args[++i]:throw new ArgumentException("引数の値がありません");switch(args[i].ToLowerInvariant()){case "-mode":mode=Next();break;case "-target":while(i+1<args.Length&&!args[i+1].StartsWith('-'))targets.Add(args[++i]);if(targets.Count==0)throw new ArgumentException("-Target に値がありません");break;case "-exclude":while(i+1<args.Length&&!args[i+1].StartsWith('-'))excludes.Add(args[++i]);if(excludes.Count==0)throw new ArgumentException("-Exclude に値がありません");break;case "-outputdir":outDir=Next();break;case "-unuseddays":unused=int.Parse(Next(),System.Globalization.CultureInfo.InvariantCulture);break;case "-folderdepth":depth=int.Parse(Next(),System.Globalization.CultureInfo.InvariantCulture);break;case "-nopause":pause=true;break;case "-elevate":elevate=true;break;case "-includerawlastaccess":case "-includeremovable":break;case "-lowerpriority":break;case "-help":case "-version":break;default:throw new ArgumentException($"不明な引数: {args[i]}");}}if(!mode.Equals("Files",StringComparison.OrdinalIgnoreCase)&&!mode.Equals("Apps",StringComparison.OrdinalIgnoreCase)&&!mode.Equals("All",StringComparison.OrdinalIgnoreCase))throw new ArgumentException("Mode は Files, Apps, All のいずれかです");mode=char.ToUpperInvariant(mode[0])+mode[1..].ToLowerInvariant();return new(mode,targets.ToArray(),excludes.ToArray(),outDir,unused,depth,pause,elevate);} }
